data={}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        s=row['timeseries_id']
        if s in want:
            data.setdefault(s,{})[row['timestamp']]=float(row['value'])

def ts2dt(t): return datetime.fromisoformat(t)

def window_avg(s, start="2018-01-01", end="2019-01-01", occ=True):
    ds=data[s]
    for t in list(ds):
        d=ts2dt(t)
        if not (start<=t<end):
            del ds[t]
    # keep a copy
    vals=[]
    occ_vals=[]
    for t,v in data[s].items():
        d=ts2dt(t)
        hr=d.hour
        o= 7<=hr<17
        vals.append(v)
        if o: occ_vals.append(v)
    import statistics
    return (round(statistics.mean(vals),3) if vals else None,
            round(statistics.mean(occ_vals),3) if occ_vals else None, len(vals))

# Before mid-June: Apr-Jun1; After: Jul-Sept1
for name in ['ZONE_T','COOL_SET']:
    s = sid_zonets if name=='ZONE_T' else sid_set
    # reload
    data[s] = {t:float(v) for t,v in data[s].items()}
    # do windows
    d=data[s]
    def avg(lo,hi,o=None):
        sel=[v for t,v in d.items() if lo<=t<hi and (o is None or (7<=ts2dt(t).hour<17))]
        import statistics
        return round(statistics.mean(sel),3)
    before_all=d
    print(name,
          "Apr 01-Jun01 all", avg("2018-04-01","2018-06-01"),
          "occ", avg("2018-04-01","2018-06-01",True),
          "| Jul-Aug all", avg("2018-07-01","2018-09-01"),
          "occ", avg("2018-07-01","2018-09-01",True))

